677	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
678		\lean{MIPStarRE.QPBT.primeTauObservable_mul}
679		\lean{MIPStarRE.QPBT.primeTauObservable_pow}
680		\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
681		\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
682		\lean{MIPStarRE.QPBT.primeTauObservable_eigenvalue_pow_char}
683		\lean{MIPStarRE.QPBT.primeTauObservable_X_mul_Z}
684		\leanok
685		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
686		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
687		\begin{enumerate}
688			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
689			      \begin{equation}\label{eq:pauli-product-power}
690				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
691				      \qquad \text{and} \qquad
692				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
693			      \end{equation}
694			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
695			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
696			      $p$-th roots of unity.
697			\item For all $a, b \in \F_q^n$,
698			      % Paper equation label kept on the display it names.
699			      \begin{equation}\label{eq:twisted-fq}
700				      \tau^X(a)\, \tau^Z(b)
701				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
702			      \end{equation}
703			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
704			      $q = p$, $n = 1$ reads
705			      \begin{equation}\label{eq:twisted-fp}
706				      \sigma^X(a)\, \sigma^Z(b)
707				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
708				      \qquad \text{for all } a, b \in \F_p\;.
709			      \end{equation}
710		\end{enumerate}
711	\end{lemma}
712	\begin{proof}
713		\leanok
714		\uses{def:generalized-pauli, def:subfield-trace}
715		All identities are verified on computational basis states. For the product
716		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
717		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
718		combine by $\F_q$-linearity of the trace, and the power relation follows by
719		iterating. For the scalar twisted commutation,
720		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
721		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
722		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
723		follows by applying the scalar relation factor by factor and summing the
724		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
725		trace is the identity map, which gives \eqref{eq:twisted-fp}.
726	\end{proof}
